ALTER TABLE marketops_eeom_results DROP CONSTRAINT IF EXISTS marketops_eeom_results_score_check; ALTER TABLE marketops_eeom_results ADD CONSTRAINT marketops_eeom_results_score_check CHECK (score >= 0 AND score <= 100); UPDATE marketops_eeom_results SET score = score * 10.0, result_json = jsonb_set(result_json, '{result,score}', to_jsonb(round((result_json #>> '{result,score}')::numeric * 10.0, 2)), true) WHERE score <= 10;
